INSERT INTO learning.skill_levels (skill_id, rank, title, xp_required, sort_order, content_version)
SELECT s.id, v.rank::learning.rank_code, v.title, v.xp, v.position, 'web-v1'
FROM (VALUES
('html','E','Premiers pas',0,1),
('html','D','Fondamentaux',150,2),
('html','C','Autonomie',600,3),
('html','B','Cas complexes',1600,4),
('html','A','Composition experte',3900,5),
('html','S','Épreuves de maîtrise',18900,6),
('css','E','Premiers pas',0,1),
('css','D','Fondamentaux',150,2),
('css','C','Autonomie',600,3),
('css','B','Cas complexes',1600,4),
('css','A','Composition experte',3900,5),
('css','S','Épreuves de maîtrise',18900,6)
) AS v(skill,rank,title,xp,position)
JOIN learning.skills s ON s.slug=v.skill JOIN learning.blocks b ON b.id=s.block_id
JOIN learning.domains d ON d.id=b.domain_id AND d.slug='web';

